CREATE SCHEMA s1;
CREATE TABLE t(a INT NOT NULL, b VARCHAR(10) DEFAULT 'x', c NUMERIC(5,2), d TEXT[], e INTERVAL, f TIMESTAMP(3), g CHAR(4), h BIT(3), i BOOLEAN);
CREATE TABLE t2(j BIGINT, k SMALLINT, l REAL, m DOUBLE PRECISION, n TEXT, o DATE, p TIMESTAMPTZ, q TIME, r UUID, s BYTEA, u JSONB, w NUMERIC, x VARBIT(5), y NAME, z TIME(2) WITH TIME ZONE);
CREATE TABLE s1.u(id INT PRIMARY KEY, v TEXT);
CREATE TABLE ident(id INT GENERATED ALWAYS AS IDENTITY, n SERIAL, bd BIGINT GENERATED BY DEFAULT AS IDENTITY (START WITH 10 INCREMENT BY 5), g INT GENERATED ALWAYS AS (id * 2) STORED);
CREATE VIEW v AS SELECT a, b FROM t WHERE a > 0;
CREATE VIEW v2 AS SELECT a + 1 AS x FROM t;
CREATE VIEW v3 AS SELECT a, b FROM v;
CREATE VIEW v4 AS SELECT DISTINCT a FROM t;
CREATE VIEW v5 AS SELECT * FROM t;
CREATE VIEW v6 AS SELECT a, a + 1 AS a1 FROM t;
CREATE VIEW s1.uv AS SELECT id FROM s1.u;
CREATE MATERIALIZED VIEW mv AS SELECT a FROM t;
CREATE TABLE pt(k INT, v TEXT) PARTITION BY RANGE (k);
CREATE TABLE pt1 PARTITION OF pt FOR VALUES FROM (0) TO (10);
SELECT table_catalog, table_schema, table_name, table_type, self_referencing_column_name, reference_generation, user_defined_type_catalog, user_defined_type_schema, user_defined_type_name, is_insertable_into, is_typed, commit_action FROM information_schema.tables WHERE table_schema IN ('public', 's1') ORDER BY table_schema, table_name;
SELECT table_catalog, table_schema, table_name, check_option, is_updatable, is_insertable_into, is_trigger_updatable, is_trigger_deletable, is_trigger_insertable_into FROM information_schema.views WHERE table_schema IN ('public', 's1') ORDER BY table_schema, table_name;
SELECT table_name, column_name, ordinal_position, column_default, is_nullable, data_type, character_maximum_length, character_octet_length, numeric_precision, numeric_precision_radix, numeric_scale, datetime_precision, interval_type, interval_precision FROM information_schema.columns WHERE table_schema IN ('public', 's1') ORDER BY table_schema, table_name, ordinal_position;
SELECT table_name, column_name, character_set_catalog, character_set_schema, character_set_name, collation_catalog, collation_schema, collation_name, domain_catalog, domain_schema, domain_name, udt_catalog, udt_schema, udt_name FROM information_schema.columns WHERE table_schema IN ('public', 's1') ORDER BY table_schema, table_name, ordinal_position;
SELECT table_name, column_name, scope_catalog, scope_schema, scope_name, maximum_cardinality, dtd_identifier, is_self_referencing, is_identity, identity_generation, identity_start, identity_increment, identity_maximum, identity_minimum, identity_cycle, is_generated, generation_expression, is_updatable FROM information_schema.columns WHERE table_schema IN ('public', 's1') ORDER BY table_schema, table_name, ordinal_position;
SELECT table_schema, table_name, column_name, ordinal_position, data_type, character_maximum_length, character_octet_length, collation_name, domain_schema, domain_name, udt_name, is_nullable, is_updatable FROM information_schema.columns WHERE table_name IN ('sql_features', 'sql_sizing', 'sql_parts', 'sql_implementation_info') ORDER BY table_name, ordinal_position;
SELECT table_name, column_name, data_type, numeric_precision, numeric_precision_radix, numeric_scale, datetime_precision, collation_name, domain_name, udt_name, dtd_identifier, is_updatable FROM information_schema.columns WHERE table_schema = 'information_schema' AND table_name IN ('routines', 'triggers', 'views', '_pg_foreign_servers') ORDER BY table_name, ordinal_position;
SELECT table_schema, table_name, table_type, is_insertable_into, is_typed FROM information_schema.tables WHERE table_schema = 'information_schema' ORDER BY table_name;
SELECT table_schema, table_name, check_option, is_updatable, is_insertable_into FROM information_schema.views WHERE table_schema = 'information_schema' AND table_name IN ('columns', 'tables', 'views') ORDER BY table_name;
SELECT catalog_name, schema_name, default_character_set_catalog, default_character_set_schema, default_character_set_name, sql_path FROM information_schema.schemata ORDER BY schema_name;
SELECT schema_name, schema_owner FROM information_schema.schemata WHERE schema_name <> 'public' ORDER BY schema_name;
SELECT * FROM information_schema.information_schema_catalog_name;
SELECT * FROM information_schema.character_sets;
SELECT * FROM information_schema.sequences ORDER BY sequence_schema, sequence_name;
SELECT * FROM information_schema.column_udt_usage WHERE table_schema IN ('public', 's1') ORDER BY table_schema, table_name, column_name;
SELECT * FROM information_schema.column_column_usage ORDER BY table_name, column_name, dependent_column;
SELECT * FROM information_schema.view_table_usage WHERE view_schema IN ('public', 's1') ORDER BY view_schema, view_name, table_name;
SELECT * FROM information_schema.view_column_usage WHERE view_schema IN ('public', 's1') ORDER BY view_schema, view_name, table_name, column_name;
SELECT * FROM information_schema.element_types WHERE object_schema IN ('public', 's1') ORDER BY object_name, collection_type_identifier;
SELECT * FROM information_schema.data_type_privileges WHERE object_schema IN ('public', 's1') ORDER BY object_name, dtd_identifier;
SELECT count(*) FROM information_schema.sql_features;
SELECT * FROM information_schema.sql_features WHERE feature_id IN ('E011', 'F021', 'T321', 'B012') ORDER BY feature_id, sub_feature_id;
SELECT is_supported, count(*) FROM information_schema.sql_features GROUP BY is_supported ORDER BY 1;
SELECT * FROM information_schema.sql_parts;
SELECT * FROM information_schema.sql_implementation_info WHERE implementation_info_id <> '18';
SELECT * FROM information_schema.sql_sizing WHERE sizing_id NOT IN (100, 101);
SELECT * FROM information_schema.columns WHERE table_name = 'nothing';
SELECT * FROM information_schema.nothing;
SELECT * FROM information_schema.pg_class;
SELECT * FROM columns;
SELECT count(*) FROM pg_catalog.columns;
